// エラー通知テキストを整形（メインWFがfailした時にError Triggerが受け取るpayloadを使用）。
const d = $input.first().json;
const wf = d.workflow && d.workflow.name ? d.workflow.name : 'unknown';
const err = d.execution && d.execution.error && d.execution.error.message ? d.execution.error.message : 'unknown error';
const node = d.execution && d.execution.lastNodeExecuted ? d.execution.lastNodeExecuted : '-';
const nl = String.fromCharCode(10);
const text = ['\u26A0\uFE0F RIO n8nワークフロー失敗', 'WF: ' + wf, '失敗ノード: ' + node, 'エラー: ' + err].join(nl);
return [{ json: { notification_text: text } }];
